func IsNeedPromptMfa(org *Organization, user *User) bool {
	if org == nil || user == nil {
		return false
	}

	for _, item := range GetUserMfaItems(org, user) {
		if item.Rule == "Required" {
			if item.Name == EmailType && !user.MfaEmailEnabled {
