func (mfa *TotpMfa) Initiate(userId string, issuer string) (*MfaProps, error) {
	// Use the provided issuer (application display name), or fall back to "Casdoor" if not provided
	if issuer == "" {
		issuer = "Casdoor"
	}

	key, err := totp.Generate(totp.GenerateOpts{
		Issuer:      issuer,
		AccountName: userId,
		Period:      mfa.period,
		SecretSize:  mfa.secretSize,
		Digits:      mfa.digits,
	})
	if err != nil {
		return nil, err
	}

	mfaProps := MfaProps{
		MfaType: mfa.MfaType,
		Secret:  key.Secret(),
		URL:     key.URL(),
	}
	return &mfaProps, nil
}

func (mfa *TotpMfa) SetupVerify(passcode string, lang string) error {
	// an imported hardware token may have another time step or length, kept after its secret, see otp_token.go
	secret, period, digits := parseTotpSecret(mfa.Secret)
	result, err := totp.ValidateCustom(passcode, secret, time.Now().UTC(), totp.ValidateOpts{
		Period:    period,
		Skew:      1,
		Digits:    digits,
		Algorithm: otp.AlgorithmSHA1,
	})
	if err != nil {
		return err
	}

	if result {
		return nil
	} else {
		return errors.New("totp passcode error")
	}
}

