// @Success 200 {object} object.Organization The Response object
// @router /get-organization [get]
func (c *ApiController) GetOrganization() {
	id := c.Ctx.Input.Query("id")
	org, orgErr := object.GetOrganization(id)
	organization, err := object.GetMaskedOrganization(c.IsGlobalAdmin(), org, orgErr)
	if err != nil {
		c.ResponseError(err.Error())
		return
	}

	if organization != nil && organization.MfaRememberInHours == 0 {
		organization.MfaRememberInHours = 12
	}

	c.ResponseOk(organization)
}

// UpdateOrganization ...
// @Title UpdateOrganization
// @Tag Organization API
// @Description update organization
// @Param   id     query    string  true        "The id ( owner/name ) of the organization"
// @Param   body    body   object.Organization  true        "The details of the organization"
// @Success 200 {object} controllers.Response The Response object
// @router /update-organization [post]
func (c *ApiController) UpdateOrganization() {
	id := c.Ctx.Input.Query("id")

	var organization object.Organization
	err := json.Unmarshal(c.Ctx.Input.RequestBody, &organization)
	if err != nil {
		c.ResponseError(err.Error())
		return
	}

	if err = object.CheckIpWhitelist(organization.IpWhitelist, c.GetAcceptLanguage()); err != nil {
		c.ResponseError(err.Error())
		return
	}

	if err = object.CheckOrganizationEdition(&organization); err != nil {
		c.ResponseError(err.Error())
		return
	}

	isGlobalAdmin, _ := c.isGlobalAdmin()

	if organization.BalanceCurrency == "" {
		organization.BalanceCurrency = "USD"
	}

	oldOrganization, err := object.GetOrganization(id)
	if err != nil {
		c.ResponseError(err.Error())
		return
	}
	if err = c.checkEnterprisePolicyChange(oldOrganization, &organization); err != nil {
		c.ResponseError(err.Error())
		return
	}

	affected, err := object.UpdateOrganization(id, &organization, isGlobalAdmin, c.GetAcceptLanguage())
	if err == nil && affected {
		ee.AfterEnterprisePolicyChange(oldOrganization, &organization)
	}
	c.Data["json"] = WrapActionResponse(affected, err)
	c.ServeJSON()
}

