		return
	}
} else {
	c.ResponseError("missing passcode or recovery code")
	return
}

if c.promptMfaSetupAfterMfa(user) {
	return
}

resp = c.HandleLoggedIn(application, user, &authForm)
c.setMfaUserSession("")

