import {authConfig} from "@/auth/Auth";
import * as Setting from "@/lib/setting";
import {getDeviceId} from "@/lib/device";

export function getAccount(query: any = "") {
  return fetch(`${authConfig.serverUrl}/api/get-account${query}`, {
    method: "GET",
    credentials: "include",
    headers: {
      "Accept-Language": Setting.getAcceptLanguage(),
    },
  }).then(res => res.json());
}

export function getInitAdminStatus() {
  return fetch(`${authConfig.serverUrl}/api/get-init-admin-status`, {
    method: "GET",
    credentials: "include",
    headers: {
      "Accept-Language": Setting.getAcceptLanguage(),
    },
  }).then(res => res.json());
}

export function initAdminPassword(password: string) {
  const formData = new FormData();
  formData.append("password", password);

  return fetch(`${authConfig.serverUrl}/api/init-admin-password`, {
    method: "POST",
    credentials: "include",
    body: formData,
    headers: {
      "Accept-Language": Setting.getAcceptLanguage(),
    },
  }).then(res => res.json());
}

export function signup(values, oAuthParams) {
  return fetch(`${authConfig.serverUrl}/api/signup${oAuthParamsToQuery(oAuthParams)}`, {
    method: "POST",
    credentials: "include",
    body: JSON.stringify(values),
    headers: {
      "Content-Type": "application/json",
      "Accept-Language": Setting.getAcceptLanguage(),
    },
  }).then(res => res.json());
}

export function getEmailAndPhone(organization, username) {
  return fetch(`${authConfig.serverUrl}/api/get-email-and-phone?organization=${organization}&username=${encodeURIComponent(username)}`, {
    method: "GET",
    credentials: "include",
    headers: {
      "Accept-Language": Setting.getAcceptLanguage(),
    },
  }).then((res) => res.json());
}

export function casLoginParamsToQuery(casParams) {
  return `?type=${casParams?.type}&id=${casParams?.id}&redirectUri=${casParams?.service}`;
}

export function oAuthParamsToQuery(oAuthParams) {
  // login
  if (oAuthParams === null || oAuthParams === undefined) {
    return "";
  }

  const resourceQuery = oAuthParams.resource
    ? `&resource=${encodeURIComponent(oAuthParams.resource)}`
    : "";
  // prompt=login and max_age decide whether the existing session is enough to sign in
  const promptQuery = oAuthParams.prompt
    ? `&prompt=${encodeURIComponent(oAuthParams.prompt)}`
    : "";
  const maxAgeQuery = oAuthParams.maxAge
    ? `&max_age=${encodeURIComponent(oAuthParams.maxAge)}`
    : "";
  // the organization a URL client_id (client ID metadata document) is added to
  const organizationQuery = oAuthParams.organization
    ? `&organization=${encodeURIComponent(oAuthParams.organization)}`
    : "";

  // code
  return `?clientId=${encodeURIComponent(oAuthParams.clientId)}&responseType=${encodeURIComponent(oAuthParams.responseType)}&redirectUri=${encodeURIComponent(oAuthParams.redirectUri)}&type=${encodeURIComponent(oAuthParams.type)}&scope=${encodeURIComponent(oAuthParams.scope)}&state=${encodeURIComponent(oAuthParams.state)}&nonce=${encodeURIComponent(oAuthParams.nonce)}&code_challenge_method=${encodeURIComponent(oAuthParams.challengeMethod)}&code_challenge=${encodeURIComponent(oAuthParams.codeChallenge)}${resourceQuery}${promptQuery}${maxAgeQuery}${organizationQuery}`;
}

export function getApplicationLogin(params) {
  let queryParams = "";
  if (params?.type === "cas") {
    queryParams = casLoginParamsToQuery(params);
  } else if (params?.type === "device") {
    queryParams = `?userCode=${params.userCode}&type=device`;
  } else {
    queryParams = oAuthParamsToQuery(params);
  }
  return fetch(`${authConfig.serverUrl}/api/get-app-login${queryParams}`, {
    method: "GET",
    credentials: "include",
    headers: {
      "Accept-Language": Setting.getAcceptLanguage(),
    },
  }).then(res => res.json());
}
