	*MfaProps
}

func (mfa *WebauthnMfa) Initiate(userId string, issuer string) (*MfaProps, error) {
	return &MfaProps{
		MfaType: WebAuthnType,
	}, nil
}

func (mfa *WebauthnMfa) SetupVerify(passcode string, lang string) error {
	return fmt.Errorf("WebAuthn MFA must be set up with the WebAuthn signup API")
}

func (mfa *WebauthnMfa) Enable(user *User) error {
	if len(user.WebauthnCredentials) == 0 {
		return fmt.Errorf("no WebAuthn credential has been registered")
	}

	columns := []string{"mfa_webauthn_enabled", "preferred_mfa_type"}
	user.MfaWebAuthnEnabled = true
	if user.PreferredMfaType == "" {
		user.PreferredMfaType = WebAuthnType
	}

	_, err := UpdateUser(user.GetId(), user, columns, false)
	return err
}

func (mfa *WebauthnMfa) Verify(passcode string, lang string) error {
	return fmt.Errorf("WebAuthn assertions must be verified with the WebAuthn signin API")
}

func NewWebauthnMfaUtil(config *MfaProps) *WebauthnMfa {
	if config == nil {
		config = &MfaProps{
			MfaType: WebAuthnType,
		}
	}
	return &WebauthnMfa{
		MfaProps: config,
	}
}

