	Action       string `xorm:"varchar(500)" json:"action"`
	ExpireTime   int64  `json:"expireTime"`
	RedeemedTime string `xorm:"varchar(100)" json:"redeemedTime"`
}

type StepUpClaims struct {
	TokenType string   `json:"tokenType"`
